class ResearchWorkspace extends StatefulWidget {
  const ResearchWorkspace({super.key,required this.model,this.strategy=false});
  final ProductState model;final bool strategy;
  @override State<ResearchWorkspace> createState()=>_ResearchWorkspaceState();
}
class _ResearchWorkspaceState extends State<ResearchWorkspace>{
  String? symbol;int fast=10,slow=30;TradingSession? result;String? error;
  final events=const [
    ('2008-09-15','Global Financial Crisis','Lehman Brothers filed for bankruptcy.','Federal Reserve history','https://www.federalreservehistory.org/essays/great-recession-and-its-aftermath'),
    ('2015-01-15','Swiss franc shock','The Swiss National Bank removed the exchange rate floor.','SNB','https://www.snb.ch/'),
    ('2016-06-23','Brexit referendum','The United Kingdom voted on EU membership.','UK Parliament','https://www.parliament.uk/'),
    ('2020-03-11','COVID-19 pandemic','WHO characterized COVID-19 as a pandemic.','WHO','https://www.who.int/'),
    ('2022-02-24','Global market shock','Russia launched its full-scale invasion of Ukraine.','United Nations','https://www.un.org/')];
  Widget small(String s)=>Text(s,style:const TextStyle(fontSize:11,color:FinTheme.steel));
  Widget number(String s)=>Text(s,style:const TextStyle(fontSize:23,fontWeight:FontWeight.w500));
  Widget stat(String title,String value,String description)=>Panel(padding:15,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[small(title),const SizedBox(height:10),FittedBox(fit:BoxFit.scaleDown,alignment:Alignment.centerLeft,child:number(value)),const SizedBox(height:6),small(description)]));
  Widget table(Widget child)=>LayoutBuilder(builder:(_,c)=>SingleChildScrollView(scrollDirection:Axis.horizontal,child:ConstrainedBox(constraints:BoxConstraints(minWidth:c.maxWidth),child:child)));
  List<MarketSeries> get rows=>widget.model.series.values.toList();
  String pct(double n)=>terminalPct(n*100);
  void run(){try{final data=widget.model.series[symbol]??rows.first;final next=backtest(data,fast:fast,slow:slow);setState((){result=next;error=null;});}catch(e){setState(()=>error='$e');}}
  Widget strategy(){final s=result;return Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[
    Text('Strategy lab',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:6),small('Reproducible long/flat moving-average strategy · simulated execution · AUD account'),const SizedBox(height:16),
    DeskPanel(title:'Experiment configuration',child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[small('DATASET'),DropdownButton<String>(isExpanded:true,value:widget.model.series.containsKey(symbol)?symbol:rows.first.symbol,items:rows.map((s)=>DropdownMenuItem(value:s.symbol,child:Text(s.symbol,overflow:TextOverflow.ellipsis))).toList(),onChanged:(v)=>setState((){symbol=v;result=null;})),const SizedBox(height:8),Wrap(spacing:18,runSpacing:8,crossAxisAlignment:WrapCrossAlignment.center,children:[small('Fast SMA'),DropdownButton<int>(value:fast,items:[5,10,15,20].map((n)=>DropdownMenuItem(value:n,child:Text('$n bars'))).toList(),onChanged:(v)=>setState((){fast=v!;result=null;})),small('Slow SMA'),DropdownButton<int>(value:slow,items:[25,30,50,80].map((n)=>DropdownMenuItem(value:n,child:Text('$n bars'))).toList(),onChanged:(v)=>setState((){slow=v!;result=null;})),MotionButton(label:'Run backtest',icon:Icons.play_arrow,onPressed:run)]),const SizedBox(height:8),small('Starting capital A\$100,000 · allocation 95% · next-bar fills · spread 2 bps · fee 1 bp · slippage 1 bp'),if(error!=null)Text(error!,style:const TextStyle(color:FinTheme.loss))])),const SizedBox(height:10),
    if(s!=null)...[LayoutBuilder(builder:(_,c){final columns=c.maxWidth>=740?4:2;return Wrap(spacing:8,runSpacing:8,children:[for(final x in [('Net return',pct(s.totalReturn),'Mark-to-market'),('Max drawdown',pct(s.drawdown),'Peak to trough'),('Sharpe',s.sharpe?.toStringAsFixed(2)??'N/A','Annualized estimate'),('Fills','${s.fills.length}','Simulated')])SizedBox(width:(c.maxWidth-8*(columns-1))/columns,child:stat(x.$1,x.$2,x.$3))]);}),const SizedBox(height:10),DeskPanel(title:'Equity curve',child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[number('A\$${formatAmount(s.equity)}'),small(s.series.source),const SizedBox(height:12),MarketChart(values:s.equityHistory),const SizedBox(height:8),small('Open positions are marked at the final observed price; no forced terminal liquidation.') ])),const SizedBox(height:10),DeskPanel(title:'Execution log',child:table(DataTable(columns:const [DataColumn(label:Text('Date')),DataColumn(label:Text('Units')),DataColumn(label:Text('Price')),DataColumn(label:Text('Fee / AUD')),DataColumn(label:Text('Realized / AUD'))],rows:[for(final f in s.fills.reversed.take(100))DataRow(cells:[for(final k in ['date','units','price','fee','realized'])DataCell(Text(f[k] is num?(f[k] as num).toStringAsFixed(k=='price'?4:2):'${f[k]}'))])])))]else const Panel(child:Padding(padding:EdgeInsets.symmetric(vertical:28),child:Center(child:Text('Configure a strategy and run a backtest.'))))]);}
  Widget research(){final candidates=rows.take(12).toList();final ranked=rows.map(MarketMetrics.new).toList()..sort((a,b)=>b.change(20).compareTo(a.change(20)));return Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('Market research',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:6),small('Cross-asset research · local observations, not live market quotes'),const SizedBox(height:14),DeskPanel(title:'Cross-asset performance / 20 observations',child:Column(children:[for(final m in ranked.take(14))Padding(padding:const EdgeInsets.symmetric(vertical:5),child:Row(children:[SizedBox(width:math.min(105.0,MediaQuery.sizeOf(context).width*.24),child:Text(m.series.symbol,maxLines:1,overflow:TextOverflow.ellipsis)),Expanded(child:LayoutBuilder(builder:(_,c)=>Align(alignment:Alignment.centerLeft,child:Container(width:c.maxWidth*(m.change(20).abs()/20).clamp(.015,1).toDouble(),height:12,decoration:BoxDecoration(color:terminalColor(m.change(20)).withAlpha(170),borderRadius:BorderRadius.circular(2)))))),const SizedBox(width:10),SizedBox(width:75,child:Text(terminalPct(m.change(20)),textAlign:TextAlign.end,style:TextStyle(color:terminalColor(m.change(20))))) ]))])),const SizedBox(height:10),DeskPanel(title:'Return correlation matrix',child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[small('Pearson correlation across overlapping end dates of observation-to-observation returns. N/A indicates insufficient variation or overlap.'),const SizedBox(height:10),table(DataTable(horizontalMargin:8,columnSpacing:10,columns:[const DataColumn(label:Text('Asset')),for(final s in candidates)DataColumn(label:SizedBox(width:70,child:Text(s.symbol,overflow:TextOverflow.ellipsis)))],rows:[for(final a in candidates)DataRow(cells:[DataCell(SizedBox(width:95,child:Text(a.symbol,overflow:TextOverflow.ellipsis))),for(final b in candidates)DataCell(Builder(builder:(_){final v=correlation(a,b);return Container(width:70,height:28,alignment:Alignment.center,color:v==null?FinTheme.rail:terminalColor(v).withAlpha((35+v.abs()*120).round()),child:Text(v?.toStringAsFixed(2)??'N/A',style:const TextStyle(fontSize:11)));}))])]))])),const SizedBox(height:10),DeskPanel(title:'Historical event archive',child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[small('Research mode only. Events are not shown as advance knowledge during replay.'),const SizedBox(height:10),for(final e in events)Padding(padding:const EdgeInsets.symmetric(vertical:10),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Container(width:5,height:50,color:FinTheme.burgundy),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[small(e.$1),Text(e.$2,style:const TextStyle(fontSize:15,fontWeight:FontWeight.w500)),Text(e.$3),small('${e.$4} · ${e.$5}')]))]))]))]);}
  @override Widget build(BuildContext context)=>widget.strategy?strategy():research();
}
